style.css:
/* Moonlit Reverie — BandLab */

/* palette — swap these values anytime */
:root {
  --my-night: #081521;
  --my-blue: #132a40;
  --my-glass: rgba(12, 26, 43, 0.78);
  --my-border: rgba(184, 211, 241, 0.14);
  --my-text: #e3eaf4;
  --my-muted: #a0b5ca;
  --my-accent: #b4d5f4;
}

/* dreamy atmosphere */
html, body {
  background-color: var(--my-night) !important;
  color: var(--my-text) !important;
  font-family: "Inter", "Segoe UI", sans-serif !important;
}

/* background image */
body {
  background-image:
    linear-gradient(rgba(5, 14, 26, .48), rgba(5, 14, 26, .68)),
    url("https://mx.pinterest.com/pin/949344796474031419/") !important;
  background-position: center !important;
  background-size: cover !important;
  background-attachment: fixed !important;
}

/* calm, soft edges */
img, video {
  border-radius: 10px !important;
}

/* softer links */
a {
  transition: opacity .2s ease !important;
}

a:hover {
  opacity: .8 !important;
}

/* dreamy scrollbar */
::-webkit-scrollbar {
  width: 7px !important;
  height: 7px !important;
}

::-webkit-scrollbar-thumb {
  background: rgba(170, 203, 234, .25) !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}
